import { mkdir, readFile, rm, writeFile } from 'node:fs/promises'
import { isAbsolute, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { env } from '../config/env.js'

/**
 * Where attachment bytes live. Local disk here; production swaps in object
 * storage (S3 / GCS) behind the same three calls. Keys are generated by the
 * service (a UUID), never taken from a client, so they are safe path segments.
 */
export interface FileStore {
  put(key: string, data: Buffer): Promise<void>
  get(key: string): Promise<Buffer | null>
  remove(key: string): Promise<void>
}

const KEY = /^[a-f0-9-]{36}$/

function localStore(dir: string): FileStore {
  const pathFor = (key: string) => {
    if (!KEY.test(key)) throw new Error('invalid storage key')
    return join(dir, key)
  }
  let ready: Promise<unknown> | null = null
  return {
    async put(key, data) {
      ready ??= mkdir(dir, { recursive: true })
      await ready
      await writeFile(pathFor(key), data, { flag: 'wx' })
    },
    async get(key) {
      try { return await readFile(pathFor(key)) } catch (err) {
        if ((err as NodeJS.ErrnoException).code === 'ENOENT') return null
        throw err
      }
    },
    async remove(key) {
      await rm(pathFor(key), { force: true })
    },
  }
}

const packageRoot = fileURLToPath(new URL('../..', import.meta.url))
export const fileStore: FileStore = localStore(isAbsolute(env.UPLOAD_DIR) ? env.UPLOAD_DIR : resolve(packageRoot, env.UPLOAD_DIR))
